#![forbid(unsafe_code)]
use std::mem;

pub const NEIGHBORHOOD_SIZE: usize = 62;
pub const NEIGHBORHOOD_MASK: u64 = (1u64 << 62) - 1;
pub const OVERFLOW_FLAG: u64 = 1u64 << 62;
pub const MIN_GROWTH: usize = 16;
const MAX_RETRY: u32 = 2;

pub struct Bucket<K, V> { entry: Option<(K, V)>, hash: u64, infos: u64 }
impl<K, V> Bucket<K, V> {
    pub fn new() -> Self { Bucket { entry: None, hash: 0, infos: 0 } }
    pub fn is_empty(&self) -> bool { self.entry.is_none() }
    pub fn key(&self) -> Option<&K> { self.entry.as_ref().map(|e| &e.0) }
    pub fn value_mut(&mut self) -> Option<&mut V> { self.entry.as_mut().map(|e| &mut e.1) }
    pub fn hash(&self) -> u64 { self.hash }
    pub fn set_entry(&mut self, key: K, value: V, hash: u64) {
        debug_assert!(self.is_empty()); self.entry = Some((key, value)); self.hash = hash;
    }
    pub fn take_entry(&mut self) -> Option<(K, V)> { self.entry.take() }
    pub fn replace_value(&mut self, value: V) -> Option<V> {
        self.entry.as_mut().map(|e| mem::replace(&mut e.1, value))
    }
    pub fn neighborhood(&self) -> u64 { self.infos & NEIGHBORHOOD_MASK }
    pub fn has_neighbor(&self, o: usize) -> bool { debug_assert!(o < NEIGHBORHOOD_SIZE); self.infos & (1u64 << o) != 0 }
    pub fn set_neighbor(&mut self, o: usize) { debug_assert!(o < NEIGHBORHOOD_SIZE); self.infos |= 1u64 << o; }
    pub fn clear_neighbor(&mut self, o: usize) { debug_assert!(o < NEIGHBORHOOD_SIZE); self.infos &= !(1u64 << o); }
    pub fn has_overflow(&self) -> bool { self.infos & OVERFLOW_FLAG != 0 }
    pub fn set_overflow(&mut self, b: bool) { if b { self.infos |= OVERFLOW_FLAG } else { self.infos &= !OVERFLOW_FLAG } }
    pub fn clear_infos(&mut self) { self.infos = 0; }
}

#[derive(Clone, Copy, Debug)]
pub struct Policy { mask: u64, count: usize }
impl Policy {
    pub fn new(min: usize) -> Self {
        let c = if min == 0 { 0 } else { min.checked_next_power_of_two().expect("too big") };
        Policy { mask: if c == 0 { 0 } else { (c - 1) as u64 }, count: c }
    }
    pub fn bucket_for_hash(&self, h: u64) -> usize { if self.count == 0 { 0 } else { (h & self.mask) as usize } }
    pub fn bucket_count(&self) -> usize { self.count }
    pub fn next_bucket_count(&self) -> usize { if self.count == 0 { MIN_GROWTH } else { self.count * 2 } }
}

struct Ovf<K, V> { hash: u64, key: K, value: V }
enum Found { B(usize, usize), O(usize) }

pub struct Map<K, V> {
    buckets: Vec<Bucket<K, V>>,
    overflow: Vec<Ovf<K, V>>,
    growth: Policy,
    len: usize,
    mlf: f32,
}

impl<K: std::hash::Hash + Eq + Clone + std::fmt::Debug, V> Map<K, V> {
    pub fn new() -> Self { Map { buckets: Vec::new(), overflow: Vec::new(), growth: Policy::new(0), len: 0, mlf: 0.95 } }
    fn hash_of(&self, k: &K) -> u64 {
        use std::hash::{Hash, Hasher};
        struct Id(u64);
        impl Hasher for Id {
            fn write(&mut self, b: &[u8]) { for x in b { self.0 = self.0.wrapping_mul(31).wrapping_add(*x as u64) } }
            fn finish(&self) -> u64 { self.0 }
            fn write_i32(&mut self, v: i32) { self.0 = v as u64 }
            fn write_u64(&mut self, v: u64) { self.0 = v }
            fn write_usize(&mut self, v: usize) { self.0 = v as u64 }
        }
        let mut h = Id(0); k.hash(&mut h); h.finish()
    }
    fn threshold(&self) -> usize { (self.growth.bucket_count() as f64 * self.mlf as f64) as usize }
    pub fn len(&self) -> usize { self.len }
    pub fn bucket_count(&self) -> usize { self.growth.bucket_count() }
    pub fn overflow_size(&self) -> usize { self.overflow.len() }

    fn find(&self, key: &K, hash: u64) -> Option<Found> {
        if self.growth.bucket_count() == 0 { return None }
        let i = self.growth.bucket_for_hash(hash);
        let mut nb = self.buckets[i].neighborhood();
        while nb != 0 {
            let o = nb.trailing_zeros() as usize;
            nb &= nb - 1;
            let b = &self.buckets[i + o];
            if !b.is_empty() && b.hash() == hash {
                if b.key().map_or(false, |k| k == key) { return Some(Found::B(i, o)) }
            }
        }
        if self.buckets[i].has_overflow() {
            for (idx, e) in self.overflow.iter().enumerate() {
                if e.hash == hash && e.key == *key { return Some(Found::O(idx)) }
            }
        }
        None
    }
    pub fn get(&self, key: &K) -> Option<&V> {
        let h = self.hash_of(key);
        match self.find(key, h)? {
            Found::B(i, o) => self.buckets[i + o].entry.as_ref().map(|e| &e.1),
            Found::O(x) => Some(&self.overflow[x].value),
        }
    }
    pub fn insert(&mut self, kv: (K, V)) -> bool {
        let (k, v) = kv;
        let h = self.hash_of(&k);
        if self.find(&k, h).is_some() { return false }
        self.insert_new(k, v, h); true
    }
    fn insert_new(&mut self, key: K, value: V, hash: u64) {
        if self.growth.bucket_count() == 0 || self.len + 1 > self.threshold() {
            self.rebuild(self.growth.next_bucket_count());
        }
        let (mut k, mut v) = (key, value);
        let mut tries = 0u32;
        loop {
            match self.try_place(k, v, hash) {
                Ok(()) => { self.len += 1; return }
                Err((k2, v2)) => {
                    k = k2; v = v2;
                    if tries >= MAX_RETRY {
                        let home = self.growth.bucket_for_hash(hash);
                        self.buckets[home].set_overflow(true);
                        self.overflow.push(Ovf { hash, key: k, value: v });
                        self.len += 1; return
                    }
                    tries += 1;
                    self.rebuild(self.growth.next_bucket_count());
                }
            }
        }
    }
    fn try_place(&mut self, key: K, value: V, hash: u64) -> Result<(), (K, V)> {
        let i = self.growth.bucket_for_hash(hash);
        let mut j = i;
        while j < self.buckets.len() && !self.buckets[j].is_empty() { j += 1 }
        if j >= self.buckets.len() { return Err((key, value)) }
        while j - i >= NEIGHBORHOOD_SIZE {
            let mut moved = false;
            for d in (1..NEIGHBORHOOD_SIZE).rev() {
                let c = j - d;
                let m = self.buckets[c].neighborhood() & ((1u64 << d) - 1);
                if m != 0 {
                    let o = m.trailing_zeros() as usize;
                    let from = c + o;
                    let fh = self.buckets[from].hash();
                    let (mk, mv) = self.buckets[from].take_entry().expect("inv");
                    self.buckets[j].set_entry(mk, mv, fh);
                    self.buckets[c].clear_neighbor(o);
                    self.buckets[c].set_neighbor(d);
                    j = from; moved = true; break
                }
            }
            if !moved { return Err((key, value)) }
        }
        self.buckets[j].set_entry(key, value, hash);
        self.buckets[i].set_neighbor(j - i);
        Ok(())
    }
    fn rebuild(&mut self, target: usize) {
        let target = if target == 0 { MIN_GROWTH } else { target.checked_next_power_of_two().unwrap() };
        let nb: Vec<Bucket<K, V>> = (0..target + NEIGHBORHOOD_SIZE - 1).map(|_| Bucket::new()).collect();
        let old_b = mem::replace(&mut self.buckets, nb);
        let old_o = mem::take(&mut self.overflow);
        self.growth = Policy::new(target);
        for mut b in old_b {
            let h = b.hash();
            if let Some((k, v)) = b.take_entry() { self.place_rehash(k, v, h) }
        }
        for e in old_o { self.place_rehash(e.key, e.value, e.hash) }
    }
    fn place_rehash(&mut self, k: K, v: V, h: u64) {
        if let Err((k, v)) = self.try_place(k, v, h) {
            let home = self.growth.bucket_for_hash(h);
            self.buckets[home].set_overflow(true);
            self.overflow.push(Ovf { hash: h, key: k, value: v });
        }
    }
    pub fn remove(&mut self, key: &K) -> Option<(K, V)> {
        let h = self.hash_of(key);
        match self.find(key, h)? {
            Found::B(i, o) => {
                let e = self.buckets[i + o].take_entry().expect("inv");
                self.buckets[i].clear_neighbor(o);
                self.len -= 1; Some(e)
            }
            Found::O(x) => {
                let e = self.overflow.remove(x);
                let home = self.growth.bucket_for_hash(e.hash);
                if !self.overflow.iter().any(|o| self.growth.bucket_for_hash(o.hash) == home) {
                    self.buckets[home].set_overflow(false);
                }
                self.len -= 1; Some((e.key, e.value))
            }
        }
    }
    pub fn check(&self) {
        let occ = self.buckets.iter().filter(|b| !b.is_empty()).count();
        assert_eq!(self.len, occ + self.overflow.len(), "inv1");
        if self.growth.bucket_count() > 0 {
            assert_eq!(self.buckets.len(), self.growth.bucket_count() + NEIGHBORHOOD_SIZE - 1, "inv7");
        }
        // inv3: every occupied bucket is claimed by exactly one home
        let mut claimed = vec![0usize; self.buckets.len()];
        for i in 0..self.growth.bucket_count() {
            let mut nb = self.buckets[i].neighborhood();
            while nb != 0 { let o = nb.trailing_zeros() as usize; nb &= nb - 1;
                assert!(o < NEIGHBORHOOD_SIZE);
                assert!(!self.buckets[i + o].is_empty(), "inv3 bit points at empty");
                assert_eq!(self.growth.bucket_for_hash(self.buckets[i + o].hash()), i, "home mismatch");
                claimed[i + o] += 1; }
        }
        for (idx, b) in self.buckets.iter().enumerate() {
            if !b.is_empty() { assert_eq!(claimed[idx], 1, "bucket {} claimed {}", idx, claimed[idx]) }
        }
        // inv5
        for e in &self.overflow {
            let home = self.growth.bucket_for_hash(e.hash);
            assert!(self.buckets[home].has_overflow(), "inv5");
        }
        for i in 0..self.growth.bucket_count() {
            if self.buckets[i].has_overflow() {
                assert!(self.overflow.iter().any(|e| self.growth.bucket_for_hash(e.hash) == i), "stale overflow flag");
            }
        }
    }
}

fn main() {
    // Case 1: sequential identity-hash keys (the test1 workload)
    for n in [0usize, 1, 2, 5, 100, 1000, 10000] {
        let mut m: Map<i32, String> = Map::new();
        for i in 0..n as i32 { assert!(m.insert((i, format!("value{}", i)))); }
        m.check();
        assert_eq!(m.len(), n);
        for i in 0..n as i32 { assert_eq!(m.get(&i).unwrap(), &format!("value{}", i)); }
        assert_eq!(m.get(&(n as i32)), None);
        println!("seq n={} buckets={} overflow={}", n, m.bucket_count(), m.overflow_size());
    }
    // Case 2: pathological all-same-home cluster (stride = large power of two)
    let mut m: Map<i32, i32> = Map::new();
    for i in 0..3000i32 { assert!(m.insert((i * 1024, i))); m.check(); }
    println!("cluster len={} buckets={} overflow={}", m.len(), m.bucket_count(), m.overflow_size());
    for i in 0..3000i32 { assert_eq!(m.get(&(i * 1024)), Some(&i), "missing {}", i * 1024); }
    // Case 3: extreme - all keys identical hash bucket forever (stride 2^30 > any bucket_count reached)
    let mut m2: Map<i64, i64> = Map::new();
    for i in 0..300i64 { assert!(m2.insert((i << 40, i))); m2.check(); }
    println!("extreme len={} buckets={} overflow={}", m2.len(), m2.bucket_count(), m2.overflow_size());
    for i in 0..300i64 { assert_eq!(m2.get(&(i << 40)), Some(&i)); }
    // erase from extreme
    for i in (0..300i64).step_by(3) { assert!(m2.remove(&(i << 40)).is_some()); m2.check(); }
    for i in 0..300i64 { let want = i % 3 != 0; assert_eq!(m2.get(&(i << 40)).is_some(), want); }
    println!("extreme after erase len={} overflow={}", m2.len(), m2.overflow_size());
    // Case 4: randomised churn
    let mut st = 0x243F6A8885A308D3u64;
    let mut rnd = move || { st ^= st << 13; st ^= st >> 7; st ^= st << 17; st };
    let mut m3: Map<u64, u64> = Map::new();
    let mut model: std::collections::HashMap<u64, u64> = std::collections::HashMap::new();
    for step in 0..60000u64 {
        let k = rnd() % 4096;
        if rnd() % 3 == 0 {
            let a = m3.remove(&k).is_some(); let b = model.remove(&k).is_some();
            assert_eq!(a, b, "remove mismatch step {}", step);
        } else {
            let a = m3.insert((k, step)); let b = model.insert(k, step).is_none();
            assert_eq!(a, b, "insert mismatch step {}", step);
        }
        if step % 97 == 0 { m3.check(); assert_eq!(m3.len(), model.len()); }
    }
    m3.check();
    assert_eq!(m3.len(), model.len());
    for (k, _) in &model { assert!(m3.get(k).is_some(), "lost {}", k); }
    println!("churn ok len={} buckets={} overflow={}", m3.len(), m3.bucket_count(), m3.overflow_size());
    println!("ALL OK");
}
